function t5_slug(string $s): string {$s=strtolower(trim((string)preg_replace('/[^a-z0-9]+/i','-',$s),'-'));return $s?:'tenant-'.date('YmdHis');}
try{
if(($_SERVER['REQUEST_METHOD']??'')==='POST'){
