   $payload=[$city,$code,$name,$slug,$domain?:null,$status,$site,trim((string)($_POST['tagline']??''))?:null,trim((string)($_POST['logo_url']??''))?:null,trim((string)($_POST['favicon_url']??''))?:null,trim((string)($_POST['primary_color']??'#0f766e'))?:'#0f766e',trim((string)($_POST['secondary_color']??'#0f172a'))?:'#0f172a',trim((string)($_POST['accent_color']??'#22c55e'))?:'#22c55e',trim((string)($_POST['timezone']??'Asia/Karachi'))?:'Asia/Karachi',trim((string)($_POST['currency']??'PKR'))?:'PKR',trim((string)($_POST['locale']??'en-PK'))?:'en-PK',trim((string)($_POST['support_email']??''))?:null,trim((string)($_POST['support_phone']??''))?:null,max(0,min(100,(float)($_POST['revenue_share_percent']??20)))];
   if($id>0){$q=db()->prepare('UPDATE tenants SET city_id=?,code=?,name=?,slug=?,primary_domain=?,status=?,site_name=?,tagline=?,logo_url=?,favicon_url=?,primary_color=?,secondary_color=?,accent_color=?,timezone=?,currency=?,locale=?,support_email=?,support_phone=?,revenue_share_percent=? WHERE id=?');$q->execute(array_merge($payload,[$id]));tenant_audit('tenant.update','tenant',$id,'Tenant settings updated.');$tid=$id;}
   else{if(!$global)throw new RuntimeException('Only the master administrator can create tenants.');$q=db()->prepare('INSERT INTO tenants(city_id,code,name,slug,primary_domain,status,site_name,tagline,logo_url,favicon_url,primary_color,secondary_color,accent_color,timezone,currency,locale,support_email,support_phone,revenue_share_percent,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$q->execute(array_merge($payload,[$uid]));$tid=(int)db()->lastInsertId();foreach(['directory','city_content','news','blog','live','marketplace','property','jobs','classifieds','ads','ai','mobile_api','seller_pos','maps','services'] as $f)db()->prepare('INSERT IGNORE INTO tenant_features(tenant_id,feature_key,enabled) VALUES(?,?,1)')->execute([$tid,$f]);tenant_audit('tenant.create','tenant',$tid,'New tenant created.');}
   if($domain!==''){
      $q=db()->prepare('SELECT tenant_id FROM tenant_domains WHERE domain=? LIMIT 1');$q->execute([$domain]);$owner=(int)($q->fetchColumn()?:0);if($owner&&$owner!==$tid)throw new RuntimeException('This domain is already assigned to another tenant.');
      $token=hash('sha256',$domain.'|'.$tid.'|'.bin2hex(random_bytes(8)));db()->prepare("INSERT INTO tenant_domains(tenant_id,domain,is_primary,status,verification_token) VALUES(?,?,1,'pending',?) ON DUPLICATE KEY UPDATE tenant_id=VALUES(tenant_id),is_primary=1,verification_token=IF(status='verified',verification_token,VALUES(verification_token))")->execute([$tid,$domain,$token]);
   }
   current_tenant(true);$flash='Tenant saved.';
 }
 elseif($act==='add_domain'){
   $tid=(int)($_POST['tenant_id']??0);if(!$global&&$tid!==tenant_id())throw new RuntimeException('Not allowed.');$domain=t5_clean_domain((string)($_POST['domain']??''));if($domain===''||!str_contains($domain,'.'))throw new RuntimeException('Enter a valid domain name.');$q=db()->prepare('SELECT tenant_id FROM tenant_domains WHERE domain=? LIMIT 1');$q->execute([$domain]);if($q->fetchColumn())throw new RuntimeException('Domain is already mapped.');$token=hash('sha256',$domain.'|'.$tid.'|'.bin2hex(random_bytes(10)));db()->prepare("INSERT INTO tenant_domains(tenant_id,domain,is_primary,status,verification_token) VALUES(?,?,0,'pending',?)")->execute([$tid,$domain,$token]);$flash='Domain added. Verify ownership before activating it.';
 }
 elseif($act==='domain_action'){
   $did=(int)($_POST['domain_id']??0);$q=db()->prepare('SELECT d.*,t.id tenant_id FROM tenant_domains d JOIN tenants t ON t.id=d.tenant_id WHERE d.id=? LIMIT 1');$q->execute([$did]);$d=$q->fetch();if(!$d)throw new RuntimeException('Domain not found.');if(!$global&&(int)$d['tenant_id']!==tenant_id())throw new RuntimeException('Not allowed.');$op=(string)($_POST['op']??'');
