   elseif($op==='disable'){db()->prepare("UPDATE tenant_domains SET status='disabled' WHERE id=?")->execute([$did]);$flash='Domain disabled.';}
   elseif($op==='primary'){db()->prepare('UPDATE tenant_domains SET is_primary=0 WHERE tenant_id=?')->execute([(int)$d['tenant_id']]);db()->prepare("UPDATE tenant_domains SET is_primary=1,status='verified',verified_at=COALESCE(verified_at,NOW()) WHERE id=?")->execute([$did]);db()->prepare('UPDATE tenants SET primary_domain=? WHERE id=?')->execute([$d['domain'],(int)$d['tenant_id']]);$flash='Primary domain updated.';}
