 }
 elseif($act==='save_features'){
   $tid=(int)($_POST['tenant_id']??0);if(!$global&&$tid!==tenant_id())throw new RuntimeException('Not allowed.');$keys=['directory','city_content','news','blog','live','marketplace','property','jobs','classifieds','ads','ai','mobile_api','seller_pos','maps','services'];$q=db()->prepare('INSERT INTO tenant_features(tenant_id,feature_key,enabled) VALUES(?,?,?) ON DUPLICATE KEY UPDATE enabled=VALUES(enabled)');foreach($keys as $k)$q->execute([$tid,$k,isset($_POST['feature'][$k])?1:0]);$flash='Tenant features updated.';
 }
}
}catch(Throwable $e){$error=$e->getMessage();}

if($global){$tenants=db()->query('SELECT t.*,c.name city_name,(SELECT COUNT(*) FROM tenant_members tm WHERE tm.tenant_id=t.id AND tm.status=1) member_count,(SELECT COUNT(*) FROM tenant_domains td WHERE td.tenant_id=t.id AND td.status=\'verified\') domain_count FROM tenants t JOIN cities c ON c.id=t.city_id ORDER BY t.is_master DESC,t.name')->fetchAll();}
else{$q=db()->prepare('SELECT t.*,c.name city_name,(SELECT COUNT(*) FROM tenant_members tm WHERE tm.tenant_id=t.id AND tm.status=1) member_count,(SELECT COUNT(*) FROM tenant_domains td WHERE td.tenant_id=t.id AND td.status=\'verified\') domain_count FROM tenants t JOIN cities c ON c.id=t.city_id JOIN tenant_members m ON m.tenant_id=t.id WHERE m.user_id=? AND m.status=1 ORDER BY t.name');$q->execute([$uid]);$tenants=$q->fetchAll();}
$selected=(int)($_GET['tenant']??tenant_id()?:($tenants[0]['id']??0));$allowedIds=array_map(fn($r)=>(int)$r['id'],$tenants);if(!in_array($selected,$allowedIds,true))$selected=(int)($tenants[0]['id']??0);$tenant=$selected?tenant_row($selected):null;$stats=$tenant?tenant_stats($selected):[];
$cities=$global?db()->query('SELECT id,name FROM cities WHERE status=1 ORDER BY name')->fetchAll():($tenant?[['id'=>$tenant['city_id'],'name'=>$tenant['city_name']]]:[]);$users=db()->query("SELECT id,name,email,role FROM users WHERE status='active' ORDER BY name LIMIT 1000")->fetchAll();$domains=[];$members=[];$features=[];if($tenant){$q=db()->prepare('SELECT * FROM tenant_domains WHERE tenant_id=? ORDER BY is_primary DESC,id');$q->execute([$selected]);$domains=$q->fetchAll();$q=db()->prepare('SELECT tm.*,u.name,u.email,u.role user_role FROM tenant_members tm JOIN users u ON u.id=tm.user_id WHERE tm.tenant_id=? ORDER BY FIELD(tm.member_role,\'owner\',\'admin\',\'manager\',\'editor\',\'finance\',\'support\'),u.name');$q->execute([$selected]);$members=$q->fetchAll();$q=db()->prepare('SELECT feature_key,enabled FROM tenant_features WHERE tenant_id=?');$q->execute([$selected]);foreach($q->fetchAll() as $r)$features[$r['feature_key']]=(bool)$r['enabled'];}
